/**
 * The UUID is generated by the CLIENT, not the database — `id` is part of
 * the sync contract (backend/API.md: "`id` may come from the client"). This
 * way a set row has its identity before the server hears about it, and
 * `PUT .../sets/{id}` is an upsert, so a retry after network loss does not
 * create a duplicate.
 */
export function uuid(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  // Environments without Web Crypto (old WebView, Node in tests) — variant 4
  // generated from getRandomValues, or as a last resort from Math.random.
  const bytes = new Uint8Array(16);
  if (typeof crypto !== "undefined" && typeof crypto.getRandomValues === "function") {
    crypto.getRandomValues(bytes);
  } else {
    for (let index = 0; index < bytes.length; index += 1) {
      bytes[index] = Math.floor(Math.random() * 256);
    }
  }
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
